package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.graphics.Typeface;
import android.widget.*;
import org.json.*;
final class TitleDetailsDialog {
 interface Change {void done(JSONObject item,boolean deleted);}
 static void show(Context c,JSONObject item,boolean media,Change changed){
  if(item==null)return;
  NativeSheet sheet=new NativeSheet(c,media?"Detalhes do título":"Detalhes do jogo");LinearLayout body=sheet.body;
  FrameLayout artwork=new ArtworkFrame(c,ArtworkGeometry.LANDSCAPE);artwork.setBackground(AppStyle.shape(artwork,NativeTheme.panel(c),18));artwork.setClipToOutline(true);
  TextView placeholder=NativeSheet.text(c,value(item,"nome","Sem título"),18,0xffc6b8ff);placeholder.setGravity(android.view.Gravity.CENTER);artwork.addView(placeholder,new FrameLayout.LayoutParams(-1,-1));
  ImageView art=new ImageView(c);art.setScaleType(ImageView.ScaleType.FIT_CENTER);artwork.addView(art,new FrameLayout.LayoutParams(-1,-1));body.addView(artwork,new LinearLayout.LayoutParams(-1,-2));MobileArtworkLoader.load(art,item,media,false);
  TextView title=NativeSheet.text(c,value(item,"nome","Sem título"),25,0xfff3f4f8);title.setTypeface(null,Typeface.BOLD);body.addView(title);
  TextView status=NativeSheet.text(c,value(item,"status","Sem status"),14,0xffc6b8ff);status.setPadding(NativeSheet.dp(c,14),NativeSheet.dp(c,10),NativeSheet.dp(c,14),NativeSheet.dp(c,10));status.setBackground(AppStyle.shape(status,NativeTheme.panel(c),12));body.addView(status);
  row(c,body,media?"Onde assistir":"Horas jogadas",media?value(item,"onde","—"):HoursDisplay.format(item.opt("horas")));
  row(c,body,"Sua avaliação",value(item,"nota","Ainda não avaliado"));
  if(!media&&!item.isNull("conquistas")){double earned=item.optDouble("conquistas",Double.NaN);if(Double.isFinite(earned)&&earned>=0&&earned<=100){TextView label=NativeSheet.text(c,"Conquistas · "+java.text.NumberFormat.getNumberInstance(new java.util.Locale("pt","BR")).format(earned)+"%",13,0xffc6b8ff);body.addView(label);ProgressBar progress=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(1000);progress.setProgress((int)Math.round(earned*10));progress.setContentDescription(label.getText());progress.setProgressTintList(android.content.res.ColorStateList.valueOf(NativeTheme.accent(c)));body.addView(progress,new LinearLayout.LayoutParams(-1,NativeSheet.dp(c,8)));}}
  boolean writable=!item.optBoolean("_readonly")&&ItemEditInput.validId(item.optString("id",""))&&item.has("updated_at");
  if(writable){Button edit=action(c,"Editar informações",true);sheet.footer.setVisibility(android.view.View.VISIBLE);sheet.footer.addView(edit);edit.setOnClickListener(v->{sheet.busy(true);new ItemEditorDialog(c,item,media,(updated,deleted)->{sheet.dialog.dismiss();changed.done(updated,false);},()->sheet.busy(false));});
   if(media&&!LibraryCategory.classify(item.optString("tipo")).equals("filme")){Button episodes=action(c,"Atualizar episódios",false);body.addView(episodes);episodes.setOnClickListener(v->JourneySheet.progress(c,item.optString("id")));}}
  body.addView(NativeSheet.text(c,"SOBRE O TÍTULO",11,0xffa99bc7));TextView description=NativeSheet.text(c,"Buscando descrição no catálogo…",14,0xffc4ccd8);description.setTextIsSelectable(true);description.setMaxLines(6);description.setEllipsize(android.text.TextUtils.TruncateAt.END);body.addView(description);
  Button readMore=action(c,"Ler descrição completa",false);readMore.setVisibility(android.view.View.GONE);body.addView(readMore);readMore.setOnClickListener(v->{boolean expanded=description.getMaxLines()==Integer.MAX_VALUE;description.setMaxLines(expanded?6:Integer.MAX_VALUE);description.setEllipsize(expanded?android.text.TextUtils.TruncateAt.END:null);readMore.setText(expanded?"Ler descrição completa":"Recolher descrição");});
  new AccountRepository(c).catalogDescription(item,media,(rows,error)->{if(!sheet.dialog.isShowing())return;if(error!=null){description.setText("Descrição indisponível no momento.");return;}JSONObject detail=rows==null?null:rows.optJSONObject(0);String synopsis=detail==null?"":detail.optString(media?"overview":"description_raw");DescriptionCredits.show(description,synopsis.isEmpty()?"Sem descrição disponível no catálogo.":synopsis);description.post(()->{android.text.Layout layout=description.getLayout();if(layout!=null&&layout.getLineCount()>0&&(layout.getLineCount()>6||layout.getEllipsisCount(layout.getLineCount()-1)>0))readMore.setVisibility(android.view.View.VISIBLE);});});
  String steamAppid=item.optString("steam_appid");if(!media&&steamAppid.matches("[1-9][0-9]{0,9}")){body.addView(NativeSheet.text(c,"CONQUISTAS DA STEAM",11,0xffa99bc7));Button achievements=action(c,"Ver conquistas",false);body.addView(achievements);LinearLayout achievementContent=new LinearLayout(c);achievementContent.setOrientation(LinearLayout.VERTICAL);achievementContent.setVisibility(android.view.View.GONE);body.addView(achievementContent);boolean[] loaded={false};achievements.setOnClickListener(v->{if(achievementContent.getVisibility()==android.view.View.VISIBLE&&loaded[0]){achievementContent.setVisibility(android.view.View.GONE);achievements.setText("Ver conquistas");return;}achievementContent.setVisibility(android.view.View.VISIBLE);achievements.setText("Recolher conquistas");if(loaded[0])return;achievements.setEnabled(false);achievementContent.removeAllViews();achievementContent.addView(NativeSheet.text(c,"Carregando conquistas salvas…",13,0xffbfc8d5));new AccountRepository(c).steamAchievements(item,(rows,error)->{achievements.setEnabled(true);if(!sheet.dialog.isShowing())return;achievementContent.removeAllViews();if(error!=null){achievementContent.addView(NativeSheet.text(c,error,13,0xffffa8b5));return;}loaded[0]=true;renderSteamAchievements(c,achievementContent,rows==null?null:rows.optJSONObject(0));});});}
  LinearLayout extras=new LinearLayout(c);extras.setOrientation(LinearLayout.VERTICAL);extras.setVisibility(android.view.View.GONE);
  Button expand=action(c,"Mais informações ▾",false);body.addView(expand);body.addView(extras);expand.setOnClickListener(v->{boolean visible=extras.getVisibility()==android.view.View.VISIBLE;extras.setVisibility(visible?android.view.View.GONE:android.view.View.VISIBLE);expand.setText(visible?"Mais informações ▾":"Recolher informações ▴");});
  row(c,extras,media?"Tipo":"Plataforma",value(item,media?"tipo":"plataforma","—"));row(c,extras,"Lançamento",value(item,"ano","—"));
  if(media)row(c,extras,"Duração",value(item,"duracao","—"));else{row(c,extras,"Loja",value(item,"loja","—"));row(c,extras,"Prioridade",value(item,"prioridade","—"));row(c,extras,"Tempo para zerar",value(item,"tempo_est","—"));if(!item.optBoolean("_readonly")){double price=item.optDouble("preco",Double.NaN);row(c,extras,"Preço pago",Double.isFinite(price)&&price>=0?java.text.NumberFormat.getCurrencyInstance(new java.util.Locale("pt","BR")).format(price):"—");}}
  Object genres=item.opt("generos");if(genres!=null&&genres!=JSONObject.NULL)extras.addView(NativeSheet.text(c,"Gêneros • "+genres.toString().replace("[","").replace("]","").replace("\"",""),13,0xffc4b6da));
  String review=value(item,"review","");if(!review.isEmpty()){body.addView(NativeSheet.text(c,"SUAS ANOTAÇÕES",11,0xffa99bc7));TextView notes=NativeSheet.text(c,review,14,0xffc4ccd8);notes.setTextIsSelectable(true);body.addView(notes);}
  if(writable){Button list=action(c,"Guardar em lista",false);extras.addView(list);list.setOnClickListener(v->CollectionSheet.add(c,item.optString("id")));Button recommend=action(c,"Indicar a um amigo",false);extras.addView(recommend);recommend.setOnClickListener(v->CollectionSheet.recommend(c,item.optString("id")));Button remove=action(c,"Excluir da biblioteca",false);remove.setTextColor(0xffffa8b5);extras.addView(remove);remove.setOnClickListener(v->confirmDelete(c,item,media,sheet,changed));}
  sheet.show();
 }
 private static void renderSteamAchievements(Context c,LinearLayout parent,JSONObject data){if(data==null){parent.addView(NativeSheet.text(c,"Nenhuma conquista disponível.",13,0xffbfc8d5));return;}int unlocked=Math.max(0,data.optInt("unlocked")),total=Math.max(unlocked,data.optInt("total"));boolean local=data.optBoolean("local");LinearLayout summary=new LinearLayout(c);summary.setOrientation(LinearLayout.VERTICAL);summary.setPadding(NativeSheet.dp(c,16),NativeSheet.dp(c,14),NativeSheet.dp(c,16),NativeSheet.dp(c,14));summary.setBackground(AppStyle.shape(summary,0xff27213a,16));TextView count=NativeSheet.text(c,total>0?unlocked+" de "+total+" desbloqueadas":"Catálogo de conquistas",17,0xfff3f4f8);count.setTypeface(null,Typeface.BOLD);summary.addView(count);if(total>0){ProgressBar progress=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(total);progress.setProgress(Math.min(unlocked,total));progress.setProgressTintList(android.content.res.ColorStateList.valueOf(NativeTheme.accent(c)));LinearLayout.LayoutParams meter=new LinearLayout.LayoutParams(-1,NativeSheet.dp(c,8));meter.setMargins(0,NativeSheet.dp(c,10),0,NativeSheet.dp(c,8));summary.addView(progress,meter);}String observed=data.optString("observed_at");if(observed.length()>=10)observed=" · sincronizado em "+observed.substring(8,10)+"/"+observed.substring(5,7)+"/"+observed.substring(0,4);summary.addView(NativeSheet.text(c,local?"Progresso salvo pelo BatCaverna no PC"+observed:"O PC ainda não enviou um progresso local para este jogo.",12,local?0xffc6b8ff:0xffffd28a));parent.addView(summary);if(data.has("local_error"))parent.addView(NativeSheet.text(c,data.optString("local_error"),12,0xffffd28a));if(data.has("official_error"))parent.addView(NativeSheet.text(c,data.optString("official_error"),12,0xffffd28a));JSONArray list=data.optJSONArray("lista");if(list==null||list.length()==0){parent.addView(NativeSheet.text(c,"Nenhuma conquista encontrada para este jogo.",13,0xffbfc8d5));return;}for(int i=0;i<list.length();i++){JSONObject achievement=list.optJSONObject(i);if(achievement==null)continue;boolean earned=achievement.optBoolean("got");LinearLayout card=new LinearLayout(c);card.setGravity(android.view.Gravity.CENTER_VERTICAL);card.setPadding(NativeSheet.dp(c,12),NativeSheet.dp(c,12),NativeSheet.dp(c,12),NativeSheet.dp(c,12));card.setBackground(AppStyle.shape(card,earned?0xff25203a:0xff1c202b,16));LinearLayout.LayoutParams cardLayout=new LinearLayout.LayoutParams(-1,-2);cardLayout.setMargins(0,NativeSheet.dp(c,10),0,0);parent.addView(card,cardLayout);ImageView icon=new ImageView(c);icon.setScaleType(ImageView.ScaleType.CENTER_CROP);icon.setAlpha(earned?1f:.45f);card.addView(icon,new LinearLayout.LayoutParams(NativeSheet.dp(c,52),NativeSheet.dp(c,52)));String image=achievement.optString("icon");if(!image.isEmpty())AccountImageLoader.load(icon,image);LinearLayout text=new LinearLayout(c);text.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams textLayout=new LinearLayout.LayoutParams(0,-2,1);textLayout.setMargins(NativeSheet.dp(c,12),0,0,0);card.addView(text,textLayout);TextView name=NativeSheet.text(c,(earned?"✓ ":"")+value(achievement,"nome","Conquista"),15,earned?0xfff3f4f8:0xff98a1af);name.setTypeface(null,Typeface.BOLD);text.addView(name);String detail=achievement.optString("desc").trim();String when=achievement.optString("quando").trim();String state=earned?"Desbloqueada"+(when.isEmpty()?"":" em "+when):"Bloqueada";text.addView(NativeSheet.text(c,detail.isEmpty()?state:detail+"\n"+state,12,earned?0xffc4ccd8:0xff7f8896));}}
 private static Button action(Context c,String label,boolean primary){Button button=new Button(c);button.setText(label);AppStyle.button(button,primary);return button;}
 private static void confirmDelete(Context c,JSONObject item,boolean media,NativeSheet parent,Change changed){NativeSheet confirm=new NativeSheet(c,"Excluir da biblioteca?");parent.busy(true);confirm.dialog.setOnDismissListener(d->parent.busy(false));confirm.body.addView(NativeSheet.text(c,value(item,"nome","Título"),22,0xfff3f4f8));confirm.body.addView(NativeSheet.text(c,"Este título será removido da sua biblioteca no app e no site. Não há lixeira no app. Isso não remove o jogo da sua conta Steam.",14,0xffbfc8d5));TextView state=NativeSheet.text(c,"",13,0xffffa8b5);confirm.body.addView(state);Button cancel=new Button(c);cancel.setText("Manter na biblioteca");AppStyle.button(cancel,false);cancel.setOnClickListener(v->confirm.dialog.dismiss());confirm.body.addView(cancel);Button erase=new Button(c);erase.setText("Confirmar exclusão");AppStyle.button(erase,true);erase.setBackground(AppStyle.shape(erase,0xff833f58,14));confirm.body.addView(erase);erase.setOnClickListener(v->{confirm.busy(true);erase.setEnabled(false);cancel.setEnabled(false);state.setText("Excluindo…");new AccountRepository(c).deleteItem(item.optString("id",""),media,item.isNull("updated_at")?null:item.optString("updated_at",""),(rows,error)->{confirm.busy(false);if(!confirm.dialog.isShowing())return;if(error!=null){state.setText(error+" Feche e confira a biblioteca antes de tentar novamente.");cancel.setEnabled(true);return;}confirm.dialog.dismiss();parent.dialog.dismiss();android.widget.Toast.makeText(c,"Título removido da biblioteca",android.widget.Toast.LENGTH_SHORT).show();changed.done(item,true);});});confirm.show();}
 private static void row(Context c,LinearLayout parent,String label,String value){LinearLayout tile=new LinearLayout(c);tile.setOrientation(LinearLayout.VERTICAL);tile.setPadding(NativeSheet.dp(c,14),NativeSheet.dp(c,8),NativeSheet.dp(c,14),NativeSheet.dp(c,8));tile.setBackground(AppStyle.shape(tile,0xff201b2b,18));LinearLayout grid=parent.getTag() instanceof LinearLayout?(LinearLayout)parent.getTag():null;int columns=c.getResources().getConfiguration().fontScale>1.3f||c.getResources().getConfiguration().screenWidthDp<360?1:2;if(grid==null||grid.getChildCount()==columns){grid=new LinearLayout(c);parent.addView(grid);parent.setTag(grid);}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(0,NativeSheet.dp(c,10),grid.getChildCount()<columns-1?NativeSheet.dp(c,6):0,0);grid.addView(tile,lp);tile.addView(NativeSheet.text(c,label.toUpperCase(java.util.Locale.ROOT),10,0xff9ca9b8));tile.addView(NativeSheet.text(c,value,16,0xfff3f4f8));}
 private static String value(JSONObject item,String key,String fallback){String value=item.isNull(key)?fallback:item.optString(key,fallback);return value.trim().isEmpty()?fallback:value;}
}
